create table public.buyer_landed_cost_estimates (id uuid primary key default gen_random_uuid(), buyer_id uuid not null default auth.uid() references auth.users(id) on delete cascade, title text not null default 'Landed cost estimate', goods_subtotal numeric(14,2) not null default 0 check (goods_subtotal >= 0), shipping_usd numeric(14,2) not null default 0 check (shipping_usd >= 0), insurance_usd numeric(14,2) not null default 0 check (insurance_usd >= 0), duty_percent numeric(7,3) not null default 0 check (duty_percent between 0 and 100), duty_usd numeric(14,2) not null default 0 check (duty_usd >= 0), other_charges_usd numeric(14,2) not null default 0 check (other_charges_usd >= 0), estimated_total_usd numeric(14,2) not null default 0 check (estimated_total_usd >= 0), cart_snapshot jsonb not null default '[]'::jsonb check (jsonb_typeof(cart_snapshot) = 'array'), created_at timestamptz not null default now()); alter table public.buyer_landed_cost_estimates enable row level security; grant select, insert on public.buyer_landed_cost_estimates to authenticated; create policy buyer_landed_cost_read_own on public.buyer_landed_cost_estimates for select to authenticated using (buyer_id = (select auth.uid())); create policy buyer_landed_cost_insert_own on public.buyer_landed_cost_estimates for insert to authenticated with check (buyer_id = (select auth.uid()));